discrete HydrogenSupplySystem
port:
    event input real hydrogenConsumption;  // Hydrogen consumption signal
event input real hydrogenRefilled;     // Hydrogen resupply complete.
event input real supplyInterrupted;    // Supply of interruptive signals
event output real hydrogenStatus;      // Hydrogen status signal.
state:
    initial state FullTank
        when entry() then
            statehold(5);
        end;
        when receive(hydrogenConsumption) then
            transition(LowTank);
            out
                send(hydrogenStatus, 1);  // Send a low-load hydrogen signal.
end;
    end;

    state LowTank
        when entry() then
            statehold(5);
        end;
        when receive(hydrogenRefilled) then
            transition(FullTank);
            out
                send(hydrogenStatus, 0);  // Send a full hydrogen signal.
end;
        when receive(supplyInterrupted) then
            transition(SupplyInterrupted);
            out
                send(hydrogenStatus, 2);  // Send supply interruption signal
end;
    end;

    state SupplyInterrupted
        when entry() then
            statehold(5);
        end;
        when receive(hydrogenRefilled) then
            transition(FullTank);
            out
                send(hydrogenStatus, 0);  // Send a full hydrogen signal.
end;
    end;
end;
end;

discrete FuelCellSystem
port:
    event input real startSignal;          // Start the signal.
event input real stopSignal;           // Stop the signal.
event input real hydrogenNormal;       // Hydrogen is normal.
event input real faultDetected;        // Fault detection signal.
event input real maintenanceComplete;  // Maintain completed signal
event output real systemStatus;        // System status signal
state:
    initial state Standby
        when entry() then
            statehold(5);
        end;
        when receive(startSignal) then
            transition(NormalOperation);
            out
                send(systemStatus, 1);  // Send a running signal
end;
    end;

    state NormalOperation
        when entry() then
            statehold(5);
        end;
        when receive(stopSignal) then
            transition(Standby);
            out
                send(systemStatus, 0);  // Send a stand-by signal
end;
        when receive(faultDetected) then
            transition(Fault);
            out
                send(systemStatus, 2);  // Send a malfunction.
end;
    end;

    state Fault
        when entry() then
            statehold(5);
        end;
        when receive(maintenanceComplete) then
            transition(Maintenance);
            out
                send(systemStatus, 3);  // Send maintenance signal
end;
    end;

    state Maintenance
        when entry() then
            statehold(5);
        end;
        when receive(maintenanceComplete) then
            transition(Standby);
            out
                send(systemStatus, 0);  // Send a stand-by signal
end;
    end;
end;
end;

discrete PowerManagementSystem
port:
    event input real startSignal;
    event input real stopSignal;
    event input real powerGenerated;
    event input real overloadDetected;
    event input real faultDetected;
    event input real repairComplete;
    event output real systemStatus;
state:
    initial state StandbyMode
        when entry() then
            statehold(5);
        end;
        when receive(startSignal) then
            transition(NormalOperation);
            out
                send(systemStatus, 1);
        end;
    end;

    state NormalOperation
        when entry() then
            statehold(5);
        end;
        when receive(stopSignal) then
            transition(StandbyMode);
            out
                send(systemStatus, 0);
        end;
        when receive(overloadDetected) then
            transition(Overload);
            out
                send(systemStatus, 2);
        end;
        when receive(faultDetected) then
            transition(Fault);
            out
                send(systemStatus, 3);
        end;
    end;

    state Overload
        when entry() then
            statehold(5);
        end;
        when receive(powerGenerated) then
            transition(NormalOperation);
            out
                send(systemStatus, 1);
        end;
    end;

    state Fault
        when entry() then
            statehold(5);
        end;
        when receive(repairComplete) then
            transition(StandbyMode);
            out
                send(systemStatus, 0);
        end;
    end;
end;
end;

